// Parse RSS XML and extract articles for this topic
const rssText = $json.data || $json.body || '';
const topicName = $('3. IF — Active Topics Only').item.json['Topic'];
const maxArticles = parseInt($('3. IF — Active Topics Only').item.json['Max Articles']) || 3;

if (!rssText || rssText.trim().length === 0) {
  return [{ json: { topic: topicName, articles: [], hasArticles: false } }];
}

// Extract items from RSS XML using regex
const itemMatches = rssText.match(/<item>([\s\S]*?)<\/item>/g) || [];

const articles = [];

for (const item of itemMatches) {
  if (articles.length >= maxArticles) break;

  const titleMatch = item.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) ||
                     item.match(/<title>([^<]*)<\/title>/);
  const title = titleMatch ? titleMatch[1].trim() : 'No Title';

  const linkMatch = item.match(/<link>([^<]*)<\/link>/) ||
                    item.match(/<link\/>([^<]+)/);
  const link = linkMatch ? linkMatch[1].trim() : '';

  const descMatch = item.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) ||
                    item.match(/<description>([^<]*)<\/description>/);
  const rawDesc = descMatch ? descMatch[1].trim() : '';
  const description = rawDesc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

  const sourceMatch = item.match(/<source[^>]*>([^<]*)<\/source>/);
  const source = sourceMatch ? sourceMatch[1].trim() : 'Google News';

  const dateMatch = item.match(/<pubDate>([^<]*)<\/pubDate>/);
  const pubDateStr = dateMatch ? dateMatch[1].trim() : '';
  const pubDate = pubDateStr ? new Date(pubDateStr) : new Date();

  const timeAgo = getTimeAgo(pubDate);

  if (title && title !== 'No Title') {
    articles.push({
      title,
      link,
      description: description.substring(0, 300),
      source,
      pubDate: pubDate.toISOString(),
      timeAgo
    });
  }
}

function getTimeAgo(date) {
  const now = new Date();
  const diffMs = now - date;
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffMins = Math.floor(diffMs / (1000 * 60));
  if (diffMins < 60) return `${diffMins} minutes ago`;
  if (diffHours < 24) return `${diffHours} hours ago`;
  return `${Math.floor(diffHours / 24)} days ago`;
}

return [{
  json: {
    topic: topicName,
    articles,
    hasArticles: articles.length > 0,
    articleCount: articles.length
  }
}];

// Split articles array into individual items for AI processing
const topicData = $json;
const articles = topicData.articles || [];

return articles.map(article => ({
  json: {
    topic: topicData.topic,
    title: article.title,
    link: article.link,
    description: article.description,
    source: article.source,
    timeAgo: article.timeAgo,
    pubDate: article.pubDate
  }
}));

