// Collect all summarized articles and build HTML email
const allItems = $input.all();

if (allItems.length === 0) {
  return [{ json: { htmlEmail: '<p>No news found today.</p>', articleCount: 0, topicCount: 0 } }];
}

// Group articles by topic
const groupedByTopic = {};
for (const item of allItems) {
  const topic = item.json.topic || 'General';
  if (!groupedByTopic[topic]) {
    groupedByTopic[topic] = [];
  }
  groupedByTopic[topic].push({
    title: item.json.title || '',
    link: item.json.link || '#',
    summary: item.json.output || item.json.summary || 'Summary not available.',
    source: item.json.source || 'News',
    timeAgo: item.json.timeAgo || 'Recently'
  });
}

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const totalTopics = Object.keys(groupedByTopic).length;
const totalArticles = allItems.length;

// Topic emoji map
const topicEmojis = {
  'AI News': '🤖',
  'Cricket': '🏏',
  'Bitcoin': '₿',
  'n8n': '⚙️',
  'Startup India': '🚀',
  'default': '📰'
};

// Build HTML sections per topic
let topicSectionsHtml = '';
for (const [topic, articles] of Object.entries(groupedByTopic)) {
  const emoji = topicEmojis[topic] || topicEmojis['default'];

  let articlesHtml = '';
  for (const article of articles) {
    const summaryLines = article.summary
      .split('\n')
      .map(l => l.trim())
      .filter(l => l.length > 0)
      .slice(0, 3);
    const summaryHtml = summaryLines.map(line => `<p style="margin:4px 0;font-size:14px;color:#444;line-height:1.6;">${line}</p>`).join('');

    articlesHtml += `
      <div style="padding:16px;margin-bottom:12px;background:#ffffff;border-radius:8px;border-left:3px solid #4A90E2;">
        <h3 style="margin:0 0 6px;font-size:15px;font-weight:600;color:#1a1a1a;line-height:1.4;">
          <a href="${article.link}" style="color:#1a1a1a;text-decoration:none;">${article.title}</a>
        </h3>
        <p style="margin:0 0 8px;font-size:12px;color:#888;">📌 ${article.source} &nbsp;•&nbsp; ${article.timeAgo}</p>
        ${summaryHtml}
        <a href="${article.link}" style="display:inline-block;margin-top:10px;font-size:12px;color:#4A90E2;text-decoration:none;font-weight:500;">Read full article →</a>
      </div>`;
  }

  topicSectionsHtml += `
    <div style="margin-bottom:28px;">
      <div style="background:#1a1a1a;padding:12px 20px;border-radius:6px;margin-bottom:12px;">
        <h2 style="margin:0;font-size:16px;color:#ffffff;font-weight:700;letter-spacing:0.5px;">
          ${emoji} ${topic.toUpperCase()}
        </h2>
      </div>
      ${articlesHtml}
    </div>`;
}

const htmlEmail = `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f4f4f4;font-family:Arial,sans-serif;">
  <div style="max-width:620px;margin:0 auto;background:#f4f4f4;padding:20px 0;">
    <div style="background:#1a1a1a;padding:28px 32px;text-align:center;border-radius:8px 8px 0 0;">
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">☀️ Your Daily News Digest</h1>
      <p style="margin:8px 0 0;color:#aaaaaa;font-size:13px;">${today}</p>
    </div>
    <div style="background:#4A90E2;padding:10px 32px;">
      <p style="margin:0;color:#ffffff;font-size:13px;text-align:center;">
        📊 ${totalTopics} topics &nbsp;•&nbsp; ${totalArticles} articles &nbsp;•&nbsp; All summaries powered by AI
      </p>
    </div>
    <div style="background:#f4f4f4;padding:24px 20px;">
      ${topicSectionsHtml}
    </div>
    <div style="background:#1a1a1a;padding:16px 32px;text-align:center;border-radius:0 0 8px 8px;">
      <p style="margin:0;color:#888888;font-size:11px;">Your personalized news digest • Powered by n8n + GPT-4o-mini</p>
      <p style="margin:6px 0 0;color:#888888;font-size:11px;">To add or remove topics, update your Google Sheet</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    htmlEmail,
    articleCount: totalArticles,
    topicCount: totalTopics,
    digestDate: today
  }
}];
